CREATE TABLE `la_article` (
  `id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '主键',
  `cid` int unsigned NOT NULL COMMENT '分类',
  `title` varchar(200) NOT NULL DEFAULT '' COMMENT '标题',
  `intro` varchar(200) NOT NULL DEFAULT '' COMMENT '简介',
  `summary` varchar(200) DEFAULT '' COMMENT '摘要',
  `image` varchar(200) NOT NULL DEFAULT '' COMMENT '封面',
  `content` text COMMENT '内容',
  `author` varchar(32) NOT NULL DEFAULT '' COMMENT '作者',
  `visit` int unsigned NOT NULL DEFAULT '0' COMMENT '浏览',
  `sort` int unsigned NOT NULL DEFAULT '50' COMMENT '排序',
  `is_show` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '是否显示: 0=否, 1=是',
  `review_status` tinyint unsigned NOT NULL DEFAULT '2' COMMENT '0草稿 1待审核 2通过 3驳回',
  `review_remark` varchar(255) NOT NULL DEFAULT '' COMMENT '审核备注',
  `review_time` int unsigned NOT NULL DEFAULT '0' COMMENT '审核时间',
  `review_admin_id` int unsigned NOT NULL DEFAULT '0' COMMENT '审核管理员ID',
  `is_delete` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '是否删除: 0=否, 1=是',
  `create_time` int unsigned NOT NULL DEFAULT '0' COMMENT '创建时间',
  `update_time` int unsigned NOT NULL DEFAULT '0' COMMENT '更新时间',
  `delete_time` int unsigned NOT NULL DEFAULT '0' COMMENT '删除时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `cid_idx` (`cid`) USING BTREE COMMENT '分类索引'
) ENGINE=InnoDB AUTO_INCREMENT=24 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='文章资讯表';
