INSERT INTO `uied_social_media_item` VALUES (1,'cmkh08y3a0006116uy8zmf1xq',3,'公众号','wechat_official',NULL,NULL,'http://localhost:3001/uploads/upload-1768575596353-677543248.webp',NULL,NULL,0,1,0,1768575599,1772900547,0),(2,'cmkh0dgg60008116uvx86kwxt',2,'设计交流群','wechat_group',NULL,NULL,NULL,NULL,'{\"groups\": [\"UIED.CN用户体验交流群⑩\", \"UIED.CN用户体验交流群2\"]}',0,1,0,1768575809,1768575809,0),(3,'cmkh0ff6k000a116ut8rnie7a',2,'添加联系方式','other',NULL,'https://www.uied.cn/wechat','http://localhost:3001/uploads/upload-1768575899061-165506919.png','为了更好的发展，根据情况制定了如下规则，需要些规范来提升它的价值，同时降低打扰到别人，不然就失去建群的初衷。希望大家积极配合，自觉遵守！\n\n建群的目的：促进设计师之间的交流、学习、合作等。（包括衣食住行吃喝玩乐）\n\n设计师的吐槽平台，这里没有老板没有甲方，只有上班的日常吃喝玩乐，衣食住行，不再重复每天乏味的上班生活!',NULL,1,1,0,1768575901,1768575927,0);
